import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 7
    reader = csv.reader(io.StringIO(raw_csv.lstrip("\ufeff"), newline=""), delimiter=",", quotechar='"', strict=False)
    records = list(reader)

    header_index = None
    for index, row in enumerate(records):
        if len(row) != expected_width:
            continue
        normalized = [cell.strip().lower() for cell in row]
        simple = all(cell and re.fullmatch(r"[\w ]+", cell) for cell in normalized)
        has_url = any(cell == "url" for cell in normalized)
        has_error = any(cell in ("erro", "error") for cell in normalized)
        if simple and has_url and has_error:
            header_index = index
            break

    if header_index is None:
        header_index = next((i for i, row in enumerate(records) if row), None)
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [str(value) for value in records[header_index]]
    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [",".join(columns[expected_width - 1:])]

    rows = []
    for record in records[header_index + 1:]:
        if not record:
            continue
        values = [str(value) for value in record]
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [",".join(values[expected_width - 1:])]
        rows.append(values)

    return {"columns": columns, "rows": rows}
